using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using System.Security.Claims;
using System.Text.RegularExpressions;

namespace MLInferenceServer.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class InferenceController : ControllerBase
    {
        private readonly ITenantModelStore _modelStore;
        private readonly IInferenceEngine _engine;
        private static readonly Encoding _utf8NoBom = new UTF8Encoding(false);

        public InferenceController(ITenantModelStore modelStore, IInferenceEngine engine)
        {
            _modelStore = modelStore;
            _engine = engine;
        }

        [HttpPost("predict/{modelName}")]
        public async Task<IActionResult> Predict(string modelName, [FromBody] PredictionRequest request)
        {
            var tenantId = GetTenantId();
            if (string.IsNullOrEmpty(tenantId))
                return Unauthorized();

            var sanitizedModelName = SanitizeModelIdentifier(modelName);
            if (sanitizedModelName == null)
                return BadRequest("Invalid model name");

            var modelPath = await ResolveModelPath(tenantId, sanitizedModelName);
            if (modelPath == null)
                return NotFound("Model not found");

            var inputTensor = PrepareInputTensor(request.Features, request.Encoding);
            if (inputTensor == null)
                return BadRequest("Invalid input features");

            var result = await _engine.RunInference(modelPath, inputTensor);
            return Ok(new PredictionResponse { Predictions = result });
        }

        private string GetTenantId()
        {
            return User.FindFirst("tenant_id")?.Value;
        }

        private string SanitizeModelIdentifier(string modelName)
        {
            if (string.IsNullOrWhiteSpace(modelName) || modelName.Length > 128)
                return null;

            // Allow alphanumeric, hyphens, underscores, dots
            if (!Regex.IsMatch(modelName, @"^[a-zA-Z0-9._\-]+$"))
                return null;

            // Block path traversal
            if (modelName.Contains("..") || modelName.Contains("/") || modelName.Contains("\\"))
                return null;

            return modelName;
        }

        private async Task<string> ResolveModelPath(string tenantId, string modelName)
        {
            // Normalize tenant ID to filesystem-safe representation
            var normalizedTenant = NormalizeTenantForPath(tenantId);
            var basePath = Path.Combine("/models", normalizedTenant);
            var fullPath = Path.Combine(basePath, modelName + ".onnx");

            // Verify the resolved path is within tenant boundary
            var canonicalBase = Path.GetFullPath(basePath);
            var canonicalFull = Path.GetFullPath(fullPath);

            if (!canonicalFull.StartsWith(canonicalBase))
                return null;

            if (await _modelStore.ExistsAsync(canonicalFull))
                return canonicalFull;

            return null;
        }

        private string NormalizeTenantForPath(string tenantId)
        {
            // Tenant IDs come as UTF-8 strings from JWT claims
            // Normalize to NFC form for consistent filesystem paths
            var normalized = tenantId.Normalize(NormalizationForm.FormC);

            // Convert to bytes and create hex-safe directory name
            var bytes = _utf8NoBom.GetBytes(normalized);
            return ConvertToSafeDirectoryName(bytes);
        }

        private string ConvertToSafeDirectoryName(byte[] input)
        {
            // Use base64url encoding for directory names
            var encoded = Convert.ToBase64String(input);
            // Make URL/filesystem safe
            encoded = encoded.Replace('+', '-').Replace('/', '_');
            // Trim padding for cleaner paths
            encoded = encoded.TrimEnd('=');
            return encoded;
        }

        private float[] PrepareInputTensor(string features, string encoding)
        {
            byte[] rawBytes;

            switch (encoding?.ToLowerInvariant())
            {
                case "base64":
                    try { rawBytes = Convert.FromBase64String(features); }
                    catch { return null; }
                    break;
                case "hex":
                    try { rawBytes = HexToBytes(features); }
                    catch { return null; }
                    break;
                case "utf8":
                case null:
                    rawBytes = _utf8NoBom.GetBytes(features);
                    break;
                default:
                    return null;
            }

            return DeserializeTensor(rawBytes);
        }

        private float[] DeserializeTensor(byte[] data)
        {
            if (data == null || data.Length == 0 || data.Length % 4 != 0)
                return null;

            var floats = new float[data.Length / 4];
            Buffer.BlockCopy(data, 0, floats, 0, data.Length);
            return floats;
        }

        private byte[] HexToBytes(string hex)
        {
            if (hex.Length % 2 != 0)
                throw new FormatException();

            var bytes = new byte[hex.Length / 2];
            for (int i = 0; i < bytes.Length; i++)
                bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            return bytes;
        }
    }

    public class PredictionRequest
    {
        public string Features { get; set; }
        public string Encoding { get; set; }
    }

    public class PredictionResponse
    {
        public float[] Predictions { get; set; }
    }

    public interface ITenantModelStore
    {
        Task<bool> ExistsAsync(string path);
    }

    public interface IInferenceEngine
    {
        Task<float[]> RunInference(string modelPath, float[] input);
    }
}
